  meetupMap: (meetupId: string) => `/v1/meetups/${meetupId}/map`,
  cancelMeetup: (meetupId: string) => `/v1/meetups/${meetupId}/cancel`,
  /** PUT = RSVP (idempotent), DELETE = withdraw. */
  rsvp: (meetupId: string) => `/v1/meetups/${meetupId}/rsvp`,
} as const;

