{
  "name": "@altair/shared",
  "version": "1.0.0",
  "private": true,
  "description": "The one shared contract: Zod request/response schemas imported by the API server and the React Native app.",
  "main": "src/index.ts",
  "types": "src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "typecheck": "tsc -p tsconfig.json",
    "test": "vitest run"
  },
  "dependencies": {
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "vitest": "^4.1.12"
  }
}

{
  "extends": "../../tsconfig.base.json",
  "include": ["src", "test"]
}

import { z } from 'zod';

export const uuidSchema = z.uuid({ message: 'Must be a valid UUID' });

export const latitudeSchema = z
  .number({ message: 'Latitude must be a number' })
  .min(-90, 'Latitude must be between -90 and 90')
  .max(90, 'Latitude must be between -90 and 90');

export const longitudeSchema = z
  .number({ message: 'Longitude must be a number' })
  .min(-180, 'Longitude must be between -180 and 180')
  .max(180, 'Longitude must be between -180 and 180');

/** ISO-8601 timestamp with an explicit offset or Z, e.g. 2026-11-07T09:00:00Z. */
export const isoDateTimeSchema = z.iso.datetime({
  offset: true,
  message: 'Must be an ISO-8601 date-time with a time zone (e.g. 2026-11-07T09:00:00Z)',
});

export const userSummarySchema = z.object({
  id: uuidSchema,
  displayName: z.string(),
});
export type UserSummary = z.infer<typeof userSummarySchema>;

import { z } from 'zod';

export const apiErrorCodes = [
  'VALIDATION_FAILED',
  'UNAUTHENTICATED',
  'FORBIDDEN',
  'NOT_FOUND',
  'MEETUP_CANCELLED',
  'MEETUP_STARTED',
  'START_TIME_NOT_IN_FUTURE',
  'INTERNAL',
] as const;

export const apiErrorCodeSchema = z.enum(apiErrorCodes);
export type ApiErrorCode = z.infer<typeof apiErrorCodeSchema>;

export const apiErrorBodySchema = z.object({
  error: z.object({
    code: apiErrorCodeSchema,
    message: z.string(),
    issues: z
      .array(z.object({ path: z.string(), message: z.string() }))
      .optional(),
  }),
});
export type ApiErrorBody = z.infer<typeof apiErrorBodySchema>;

import { z } from 'zod';
import { uuidSchema } from './common';

export const groupSchema = z.object({
  id: uuidSchema,
  name: z.string(),
});
export type Group = z.infer<typeof groupSchema>;

/** GET /v1/me/groups: only the caller's own groups. */
export const myGroupsResponseSchema = z.object({
  groups: z.array(groupSchema),
});
export type MyGroupsResponse = z.infer<typeof myGroupsResponseSchema>;

export const groupIdParamsSchema = z.strictObject({ groupId: uuidSchema });
export type GroupIdParams = z.infer<typeof groupIdParamsSchema>;

import { z } from 'zod';
import { latitudeSchema, longitudeSchema } from './common';

export const MIN_APPROXIMATE_RADIUS_METERS = 300;

/** Shown to the creator and to members who have RSVP'd. */
export const exactMeetingPointSchema = z.object({
  visibility: z.literal('exact'),
  placeName: z.string(),
  latitude: latitudeSchema,
  longitude: longitudeSchema,
});

/**
 * Shown to group members who have not RSVP'd. Computed in the database;
 * the center is offset from the exact point and the place name is withheld.
 */
export const approximateAreaSchema = z.object({
  visibility: z.literal('approximate'),
  label: z.string(),
  centerLatitude: latitudeSchema,
  centerLongitude: longitudeSchema,
  radiusMeters: z.number().int().min(MIN_APPROXIMATE_RADIUS_METERS),
});

export const meetingPointViewSchema = z.discriminatedUnion('visibility', [
  exactMeetingPointSchema,
  approximateAreaSchema,
]);

export type ExactMeetingPoint = z.infer<typeof exactMeetingPointSchema>;
export type ApproximateArea = z.infer<typeof approximateAreaSchema>;
export type MeetingPointView = z.infer<typeof meetingPointViewSchema>;

import { z } from 'zod';
import {
  isoDateTimeSchema,
  latitudeSchema,
  longitudeSchema,
  userSummarySchema,
  uuidSchema,
} from './common';
import { meetingPointViewSchema } from './location';

export const MEETUP_TITLE_MAX = 80;
export const PLACE_NAME_MAX = 120;

export const meetupStatusSchema = z.enum(['scheduled', 'cancelled']);
export type MeetupStatus = z.infer<typeof meetupStatusSchema>;

// ---------------------------------------------------------------------
// Requests
// ---------------------------------------------------------------------

/**
 * POST /v1/meetups
 *
 * Strict: unknown keys (e.g. a client-supplied `createdBy`) are rejected,
 * never silently used. The creator always comes from the verified session.
 * The future-start rule is evaluated at parse time, so the app shows it
 * early and the server re-checks it authoritatively on every request.
 */
export const createMeetupRequestSchema = z.strictObject({
  groupId: uuidSchema,
  title: z
    .string({ message: 'Title is required' })
    .trim()
    .min(1, 'Title is required')
    .max(MEETUP_TITLE_MAX, `Title must be at most ${MEETUP_TITLE_MAX} characters`),
  startsAt: isoDateTimeSchema.refine((value) => Date.parse(value) > Date.now(), {
    message: 'Start time must be in the future',
  }),
  meetingPoint: z.strictObject({
    placeName: z
      .string({ message: 'Meeting point name is required' })
      .trim()
      .min(1, 'Meeting point name is required')
      .max(PLACE_NAME_MAX, `Meeting point name must be at most ${PLACE_NAME_MAX} characters`),
    latitude: latitudeSchema,
    longitude: longitudeSchema,
  }),
});
export type CreateMeetupRequest = z.infer<typeof createMeetupRequestSchema>;
/** What the form holds before parsing (title untrimmed, etc.). */
export type CreateMeetupInput = z.input<typeof createMeetupRequestSchema>;

/** Path params for /v1/meetups/:meetupId[/...] (cancel, RSVP, withdraw, reads). */
export const meetupIdParamsSchema = z.strictObject({ meetupId: uuidSchema });
export type MeetupIdParams = z.infer<typeof meetupIdParamsSchema>;

/** Cancel, RSVP and withdraw carry no body; anything sent must be empty. */
export const emptyBodySchema = z.strictObject({}).optional();

// ---------------------------------------------------------------------
// Responses
// ---------------------------------------------------------------------

export const attendeeSchema = z.object({
  userId: uuidSchema,
  displayName: z.string(),
  rsvpAt: isoDateTimeSchema,
});
export type Attendee = z.infer<typeof attendeeSchema>;

/** What the signed-in member may do with this meetup, decided on the server. */
export const meetupViewerSchema = z.object({
  isCreator: z.boolean(),
  isAttending: z.boolean(),
  canRsvp: z.boolean(),
  canCancel: z.boolean(),
});
export type MeetupViewer = z.infer<typeof meetupViewerSchema>;

export const meetupSummarySchema = z.object({
  id: uuidSchema,
  groupId: uuidSchema,
  title: z.string(),
  startsAt: isoDateTimeSchema,
  status: meetupStatusSchema,
  cancelledAt: isoDateTimeSchema.nullable(),
  creator: userSummarySchema,
  attendeeCount: z.number().int().min(0),
  viewer: meetupViewerSchema,
  meetingPoint: meetingPointViewSchema,
});
export type MeetupSummary = z.infer<typeof meetupSummarySchema>;

export const meetupDetailSchema = meetupSummarySchema.extend({
  attendees: z.array(attendeeSchema),
});
export type MeetupDetail = z.infer<typeof meetupDetailSchema>;

/** GET /v1/groups/:groupId/meetups (soonest first, cancelled included). */
export const listMeetupsResponseSchema = z.object({
  meetups: z.array(meetupSummarySchema),
});
export type ListMeetupsResponse = z.infer<typeof listMeetupsResponseSchema>;

/** GET /v1/meetups/:id, and the result of create / cancel / RSVP / withdraw. */
export const meetupDetailResponseSchema = z.object({
  meetup: meetupDetailSchema,
});
export type MeetupDetailResponse = z.infer<typeof meetupDetailResponseSchema>;

/** GET /v1/meetups/:id/attendees */
export const attendeesResponseSchema = z.object({
  meetupId: uuidSchema,
  attendees: z.array(attendeeSchema),
});
export type AttendeesResponse = z.infer<typeof attendeesResponseSchema>;

export const meetupMapItemSchema = z.object({
  meetupId: uuidSchema,
  title: z.string(),
  startsAt: isoDateTimeSchema,
  status: meetupStatusSchema,
  meetingPoint: meetingPointViewSchema,
});
export type MeetupMapItem = z.infer<typeof meetupMapItemSchema>;

/** GET /v1/meetups/:id/map */
export const meetupMapResponseSchema = z.object({ item: meetupMapItemSchema });
export type MeetupMapResponse = z.infer<typeof meetupMapResponseSchema>;

/** GET /v1/groups/:groupId/map */
export const groupMapResponseSchema = z.object({
  groupId: uuidSchema,
  items: z.array(meetupMapItemSchema),
});
export type GroupMapResponse = z.infer<typeof groupMapResponseSchema>;

/** API paths, shared so the app and the server can never drift apart. */
export const apiRoutes = {
  health: '/health',
  myGroups: '/v1/me/groups',
  groupMeetups: (groupId: string) => `/v1/groups/${groupId}/meetups`,
  groupMap: (groupId: string) => `/v1/groups/${groupId}/map`,
  meetups: '/v1/meetups',
  meetup: (meetupId: string) => `/v1/meetups/${meetupId}`,
  meetupAttendees: (meetupId: string) => `/v1/meetups/${meetupId}/attendees`,
  meetupMap: (meetupId: string) => `/v1/meetups/${meetupId}/map`,
  cancelMeetup: (meetupId: string) => `/v1/meetups/${meetupId}/cancel`,
  /** PUT = RSVP (idempotent), DELETE = withdraw. */
  rsvp: (meetupId: string) => `/v1/meetups/${meetupId}/rsvp`,
} as const;

export * from './common';
export * from './errors';
export * from './groups';
export * from './location';
export * from './meetups';
export * from './routes';

