  centerLongitude: number;
  radiusMeters: number;
}

export interface ExactPointRecord {
  placeName: string;
  latitude: number;
  longitude: number;
}

/**
 * A meetup as the database lets the CURRENT member see it. `exactPoint` is
 * null unless RLS on meetup_meeting_points returned the row for them.
 */
export interface MeetupRecord {
  id: string;
  groupId: string;
  title: string;
  startsAt: Date;
  status: MeetupStatus;
  cancelledAt: Date | null;
  creatorId: string;
  creatorDisplayName: string;
  area: ApproximateAreaRecord;
  exactPoint: ExactPointRecord | null;
  /** Evaluated with the database clock, the same clock the RSVP trigger uses. */
  hasStarted: boolean;
  attendeeCount: number;
  viewerIsAttending: boolean;
}

export interface AttendeeRecord {
  meetupId: string;
  userId: string;
  displayName: string;
  rsvpAt: Date;
}

export interface NewMeetup {
  groupId: string;
  title: string;
  startsAt: Date;
  placeName: string;
  latitude: number;
  longitude: number;
}

import type { Actor, AttendeeRecord, GroupRecord, MeetupRecord, NewMeetup } from './types';

/**
 * Data-access ports. Implementations run every query AS the member (their
 * identity is bound to the transaction), so row-level security in Postgres
 * decides what each method can see or change. Services never pass a user id
 * for authorisation; they only ever get back what the member may see.
 */
export interface GroupRepository {
  /** The caller's own groups. */
  listMine(): Promise<GroupRecord[]>;
  /** The group if the caller is a member, otherwise null. */
  findVisible(groupId: string): Promise<GroupRecord | null>;
}

export interface MeetupRepository {
  /** A group's meetups visible to the caller, soonest first, cancelled included. */
  listByGroup(groupId: string): Promise<MeetupRecord[]>;
  findVisible(meetupId: string): Promise<MeetupRecord | null>;
  /** Creates as the caller (creator comes from the session). Returns the new id. */
  create(input: NewMeetup): Promise<string>;
  /** Cancels if the caller is the creator and it is still scheduled. True if a row changed. */
  cancel(meetupId: string): Promise<boolean>;
}

export interface RsvpRepository {
  listAttendees(meetupId: string): Promise<AttendeeRecord[]>;
  /** RSVPs the caller. Idempotent. */
  addForCaller(meetupId: string): Promise<void>;
  /** Withdraws the caller's RSVP. True if one existed. */
  removeForCaller(meetupId: string): Promise<boolean>;
}

export interface Repositories {
  groups: GroupRepository;
  meetups: MeetupRepository;
  rsvps: RsvpRepository;
}

/**
 * Runs work in one transaction bound to the member's identity.
 *  - read:  as the client-facing `authenticated` role, read-only.
 *  - write: as `altair_api_writer`, the only role with write grants.
 */
export interface UnitOfWork {
  read<T>(actor: Actor, work: (repos: Repositories) => Promise<T>): Promise<T>;
  write<T>(actor: Actor, work: (repos: Repositories) => Promise<T>): Promise<T>;
}

/** Verifies a Supabase access token. Returns null when it is not valid. */
export interface TokenVerifier {
  verify(accessToken: string): Promise<Actor | null>;
}

import type { MeetingPointView, MeetupViewer } from '@altair/shared';
import type { Actor, MeetupRecord } from './types';

export const APPROXIMATE_AREA_LABEL = 'Approximate area · RSVP to see the exact meeting point';

/** What this member may do with the meetup. */
export function viewerFor(meetup: MeetupRecord, actor: Actor): MeetupViewer {
  const isCreator = meetup.creatorId === actor.userId;
  const isScheduled = meetup.status === 'scheduled';
  return {
    isCreator,
    isAttending: meetup.viewerIsAttending,
    canRsvp: isScheduled && !meetup.hasStarted && !meetup.viewerIsAttending,
    canCancel: isCreator && isScheduled,
  };
}

/**
 * The meeting point this member may see.
 *
 * The database is the enforcement point: `exactPoint` is only populated when
 * RLS on meetup_meeting_points returned the row. This function is a second,
 * independent check: even if a query bug ever fetched the exact point for
 * someone who is neither the creator nor an attendee, it is not sent.
 */
export function meetingPointFor(meetup: MeetupRecord, viewer: MeetupViewer): MeetingPointView {
  const entitledToExact = viewer.isCreator || viewer.isAttending;
  if (entitledToExact && meetup.exactPoint) {
    return {
      visibility: 'exact',
      placeName: meetup.exactPoint.placeName,
      latitude: meetup.exactPoint.latitude,
      longitude: meetup.exactPoint.longitude,
    };
  }
  return {
    visibility: 'approximate',
    label: APPROXIMATE_AREA_LABEL,
    centerLatitude: meetup.area.centerLatitude,
    centerLongitude: meetup.area.centerLongitude,
    radiusMeters: meetup.area.radiusMeters,
  };
}

