import { myGroupsResponseSchema } from '@altair/shared';
import type { FastifyPluginAsync } from 'fastify';
import { actorOf } from '../../http/auth';
import { toResponse } from '../../http/validation';
import type { GroupsService } from './groups.service';

export function groupsRoutes(service: GroupsService): FastifyPluginAsync {
  return async (app) => {
    app.get('/me/groups', async (request) =>
      toResponse(myGroupsResponseSchema, await service.listMine(actorOf(request))),
    );
  };
}

import {
  attendeesResponseSchema,
  createMeetupRequestSchema,
  emptyBodySchema,
  groupIdParamsSchema,
  groupMapResponseSchema,
  listMeetupsResponseSchema,
  meetupDetailResponseSchema,
  meetupIdParamsSchema,
  meetupMapResponseSchema,
} from '@altair/shared';
import type { FastifyPluginAsync } from 'fastify';
import { actorOf } from '../../http/auth';
import { parseInput, toResponse } from '../../http/validation';
import type { MeetupsService } from './meetups.service';

export function meetupsRoutes(service: MeetupsService): FastifyPluginAsync {
  return async (app) => {
    app.get('/groups/:groupId/meetups', async (request) => {
      const { groupId } = parseInput(groupIdParamsSchema, request.params, 'path parameters');
      return toResponse(listMeetupsResponseSchema, await service.listForGroup(actorOf(request), groupId));
    });

    app.get('/groups/:groupId/map', async (request) => {
      const { groupId } = parseInput(groupIdParamsSchema, request.params, 'path parameters');
      return toResponse(groupMapResponseSchema, await service.getGroupMap(actorOf(request), groupId));
    });

    app.get('/meetups/:meetupId', async (request) => {
      const { meetupId } = parseInput(meetupIdParamsSchema, request.params, 'path parameters');
      const meetup = await service.getDetail(actorOf(request), meetupId);
      return toResponse(meetupDetailResponseSchema, { meetup });
    });

    app.get('/meetups/:meetupId/attendees', async (request) => {
      const { meetupId } = parseInput(meetupIdParamsSchema, request.params, 'path parameters');
      return toResponse(attendeesResponseSchema, await service.getAttendees(actorOf(request), meetupId));
    });

    app.get('/meetups/:meetupId/map', async (request) => {
      const { meetupId } = parseInput(meetupIdParamsSchema, request.params, 'path parameters');
      return toResponse(meetupMapResponseSchema, await service.getMeetupMap(actorOf(request), meetupId));
    });

    // ---- writes: validated with the shared contract before anything else ----

    app.post('/meetups', async (request, reply) => {
      const actor = actorOf(request);
      const input = parseInput(createMeetupRequestSchema, request.body, 'meetup');
      const meetup = await service.create(actor, input);
      return reply.status(201).send(toResponse(meetupDetailResponseSchema, { meetup }));
    });

    app.post('/meetups/:meetupId/cancel', async (request) => {
      const actor = actorOf(request);
      const { meetupId } = parseInput(meetupIdParamsSchema, request.params, 'path parameters');
      parseInput(emptyBodySchema, request.body, 'request body');
      return toResponse(meetupDetailResponseSchema, { meetup: await service.cancel(actor, meetupId) });
    });
  };
}

import { emptyBodySchema, meetupDetailResponseSchema, meetupIdParamsSchema } from '@altair/shared';
import type { FastifyPluginAsync } from 'fastify';
import { actorOf } from '../../http/auth';
import { parseInput, toResponse } from '../../http/validation';
import type { RsvpsService } from './rsvps.service';

export function rsvpsRoutes(service: RsvpsService): FastifyPluginAsync {
  return async (app) => {
    // PUT: RSVP is idempotent (RSVPing twice leaves one RSVP).
    app.put('/meetups/:meetupId/rsvp', async (request) => {
      const actor = actorOf(request);
      const { meetupId } = parseInput(meetupIdParamsSchema, request.params, 'path parameters');
      parseInput(emptyBodySchema, request.body, 'request body');
      return toResponse(meetupDetailResponseSchema, { meetup: await service.rsvp(actor, meetupId) });
    });

    app.delete('/meetups/:meetupId/rsvp', async (request) => {
      const actor = actorOf(request);
      const { meetupId } = parseInput(meetupIdParamsSchema, request.params, 'path parameters');
      parseInput(emptyBodySchema, request.body, 'request body');
      return toResponse(meetupDetailResponseSchema, { meetup: await service.withdraw(actor, meetupId) });
    });
  };
}

import Fastify, { type FastifyServerOptions } from 'fastify';
import type { TokenVerifier, UnitOfWork } from '../domain/ports';
import { GroupsService } from '../features/groups/groups.service';
import { groupsRoutes } from '../features/groups/groups.routes';
import { MeetupsService } from '../features/meetups/meetups.service';
import { meetupsRoutes } from '../features/meetups/meetups.routes';
import { RsvpsService } from '../features/rsvps/rsvps.service';
import { rsvpsRoutes } from '../features/rsvps/rsvps.routes';
import { authenticate } from './auth';
import { registerErrorHandling } from './error-handler';

export interface AppDependencies {
  uow: UnitOfWork;
  tokenVerifier: TokenVerifier;
  logger?: FastifyServerOptions['logger'];
}

/** Builds the HTTP app from its ports. No I/O happens here, so tests can inject fakes. */
export function buildApp({ uow, tokenVerifier, logger = false }: AppDependencies) {
  const app = Fastify({ logger, bodyLimit: 16 * 1024 });

  app.decorateRequest('actor', null);
  registerErrorHandling(app);

  app.get('/health', async () => ({ status: 'ok' }));

  app.register(
    async (v1) => {
      v1.addHook('onRequest', authenticate(tokenVerifier));
      await v1.register(groupsRoutes(new GroupsService(uow)));
      await v1.register(meetupsRoutes(new MeetupsService(uow)));
      await v1.register(rsvpsRoutes(new RsvpsService(uow)));
    },
    { prefix: '/v1' },
  );

  return app;
}

