  it('rejects a start time that is not in the future', async () => {
    const result = await asWriter('sam', `select app.insert_meetup($1, $2, '[test] x', now(), 'p', 40, -100)`, [groups.maple, users.sam]);
    expect(result.error).toBe('AL006');
  });

  it('member can create in their own group', async () => {
    const result = await asWriter<{ id: string }>(
      'sam',
      `select app.insert_meetup($1, $2, '[test] ok', now() + interval '1 day', 'p', 40, -100) as id`,
      [groups.maple, users.sam],
    );
    expect(result.error).toBeUndefined();
    expect(result.rows[0]?.id).toMatch(/^[0-9a-f-]{36}$/);
  });
});

describe('domain rules hold even for the database owner', () => {
  it('a cancelled meetup cannot be reopened or edited', async () => {
    await db.query(`update public.meetups set status = 'cancelled' where id = $1`, [meetups.weeknightWalk]);
    await expect(db.query(`update public.meetups set status = 'scheduled', cancelled_at = null where id = $1`, [meetups.weeknightWalk])).rejects.toMatchObject({
      code: 'AL004',
    });
  });

  it('no RSVP to a cancelled meetup', async () => {
    await db.query(`update public.meetups set status = 'cancelled' where id = $1`, [meetups.weeknightWalk]);
    await expect(
      db.query(`insert into public.rsvps (meetup_id, user_id) values ($1, $2)`, [meetups.weeknightWalk, users.sam]),
    ).rejects.toMatchObject({ code: 'AL002' });
  });

  it('no RSVP to a started meetup', async () => {
    await db.query(`update public.meetups set starts_at = now() - interval '5 minutes' where id = $1`, [meetups.weeknightWalk]);
    await expect(
      db.query(`insert into public.rsvps (meetup_id, user_id) values ($1, $2)`, [meetups.weeknightWalk, users.sam]),
    ).rejects.toMatchObject({ code: 'AL003' });
  });

  it('RSVP user must be a member of the group', async () => {
    await expect(
      db.query(`insert into public.rsvps (meetup_id, user_id) values ($1, $2)`, [meetups.saturdayLoop, users.quinn]),
    ).rejects.toMatchObject({ code: 'AL001' });
  });

  it('existing attendees can still withdraw after cancellation', async () => {
    await db.query(`update public.meetups set status = 'cancelled' where id = $1`, [meetups.saturdayLoop]);
    const result = await asWriter('jordan', `delete from public.rsvps where meetup_id = $1 and user_id = app.current_user_id()`, [
      meetups.saturdayLoop,
    ]);
    expect(result.error).toBeUndefined();
    expect(result.affected).toBe(1);
  });

  it('identity columns are immutable', async () => {
    await expect(db.query(`update public.meetups set group_id = $2 where id = $1`, [meetups.saturdayLoop, groups.riverside])).rejects.toMatchObject({
      code: 'AL005',
    });
  });
});

