import { Button } from './Button';
import { colors, spacing, typography } from './theme';

export function LoadingState({ message = 'Loading…' }: { message?: string }) {
  return (
    <View style={styles.center} accessibilityRole="progressbar" accessibilityLabel={message} testID="state-loading">
      <ActivityIndicator size="large" color={colors.primary} />
      <Text style={styles.muted}>{message}</Text>
    </View>
  );
}

export function EmptyState({ title, message, action }: { title: string; message?: string; action?: { label: string; onPress: () => void } }) {
  return (
    <View style={styles.center} testID="state-empty">
      <Text style={styles.title}>{title}</Text>
      {message ? <Text style={styles.muted}>{message}</Text> : null}
      {action ? <Button label={action.label} onPress={action.onPress} style={styles.action} /> : null}
    </View>
  );
}

