import type { NativeStackScreenProps } from '@react-navigation/native-stack';

export type RootStackParamList = {
  SignIn: undefined;
  Meetups: undefined;
  MeetupDetail: { meetupId: string; flash?: 'created' };
  CreateMeetup: { groupId: string };
};

export type ScreenProps<Name extends keyof RootStackParamList> = NativeStackScreenProps<RootStackParamList, Name>;

import { Ionicons } from '@expo/vector-icons';
import { useState } from 'react';
import { KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { z } from 'zod';
import { Banner } from '../../ui/Banner';
import { Button } from '../../ui/Button';
import { TextField } from '../../ui/TextField';
import { colors, radius, spacing, typography } from '../../ui/theme';
import { useAuth } from './AuthProvider';

const credentialsSchema = z.object({
  email: z.email('Enter a valid email address'),
  password: z.string().min(1, 'Enter your password'),
});

/** Dev-only shortcuts for the seeded accounts (emails only; the password is still typed). */
const SEED_EMAILS = ['avery', 'jordan', 'sam', 'riley', 'taylor'].map((n) => `${n}@example.test`);

export function SignInScreen() {
  const { signIn } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<{ email?: string; password?: string }>({});
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const submit = async () => {
    setError(null);
    const parsed = credentialsSchema.safeParse({ email: email.trim(), password });
    if (!parsed.success) {
      const flat = z.flattenError(parsed.error).fieldErrors;
      setFieldErrors({ email: flat.email?.[0], password: flat.password?.[0] });
      return;
    }
    setFieldErrors({});
    setSubmitting(true);
    try {
      await signIn(parsed.data.email, parsed.data.password);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Sign-in failed.');
      setSubmitting(false);
    }
  };

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView style={styles.flex} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
          <View style={styles.brand}>
            <View style={styles.logo}>
              <Ionicons name="paw" size={30} color={colors.onPrimary} />
            </View>
            <Text style={styles.appName}>Altair</Text>
            <Text style={styles.tagline}>Neighborhood dog walks, together.</Text>
          </View>

          <View style={styles.form}>
            <TextField
              label="Email"
              value={email}
              onChangeText={setEmail}
              autoCapitalize="none"
              autoComplete="email"
              keyboardType="email-address"
              textContentType="emailAddress"
              placeholder="you@example.test"
              error={fieldErrors.email}
              testID="email-input"
              returnKeyType="next"
            />
            <TextField
              label="Password"
              value={password}
              onChangeText={setPassword}
              secureTextEntry={!showPassword}
              autoCapitalize="none"
              autoComplete="password"
              textContentType="password"
              placeholder="Your password"
              error={fieldErrors.password}
              testID="password-input"
              returnKeyType="go"
              onSubmitEditing={submit}
              trailing={
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={showPassword ? 'Hide password' : 'Show password'}
                  onPress={() => setShowPassword((v) => !v)}
                  hitSlop={12}
                >
                  <Ionicons name={showPassword ? 'eye-off-outline' : 'eye-outline'} size={20} color={colors.textMuted} />
                </Pressable>
              }
            />
            {error ? <Banner tone="error" message={error} testID="sign-in-error" /> : null}
            <Button label="Sign in" onPress={submit} loading={submitting} testID="sign-in-button" />
          </View>

          {__DEV__ ? (
            <View style={styles.dev}>
              <Text style={styles.devTitle}>Seeded test accounts</Text>
              <View style={styles.devRow}>
                {SEED_EMAILS.map((seed) => (
                  <Pressable key={seed} style={styles.devChip} onPress={() => setEmail(seed)} accessibilityRole="button">
                    <Text style={styles.devChipText}>{seed.split('@')[0]}</Text>
                  </Pressable>
                ))}
              </View>
            </View>
          ) : null}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.background },
  flex: { flex: 1 },
  content: { flexGrow: 1, justifyContent: 'center', padding: spacing.xl, gap: spacing.xxl },
  brand: { alignItems: 'center', gap: spacing.sm },
  logo: {
    width: 64,
    height: 64,
    borderRadius: radius.lg,
    backgroundColor: colors.primary,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: spacing.sm,
  },
  appName: { ...typography.display, color: colors.primary },
  tagline: { ...typography.body, color: colors.textMuted },
  form: { gap: spacing.lg },
  dev: { gap: spacing.sm, alignItems: 'center' },
  devTitle: { ...typography.caption, color: colors.textMuted },
  devRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm, justifyContent: 'center' },
  devChip: { borderRadius: radius.pill, backgroundColor: colors.secondary, paddingHorizontal: spacing.md, paddingVertical: spacing.xs + 2 },
  devChipText: { ...typography.caption, color: colors.primary, fontWeight: '600' },
});

import type { MeetupSummary } from '@altair/shared';
import { Ionicons } from '@expo/vector-icons';
import { useCallback, useEffect, useLayoutEffect, useState } from 'react';
import { FlatList, Pressable, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { messageFor } from '../../../core/api/api-error';
import type { ScreenProps } from '../../../navigation/types';
import { Button } from '../../../ui/Button';
import { EmptyState, ErrorState, LoadingState } from '../../../ui/StateViews';
import { colors, spacing, typography } from '../../../ui/theme';
import { useAuth } from '../../auth/AuthProvider';
import { GroupPicker } from '../../groups/GroupPicker';
import { useMyGroups } from '../../groups/hooks';
import { MeetupCard } from '../components/MeetupCard';
import { useGroupMeetups } from '../hooks';

export function MeetupListScreen({ navigation }: ScreenProps<'Meetups'>) {
  const { signOut } = useAuth();
  const groupsQuery = useMyGroups();
  const [selectedGroupId, setSelectedGroupId] = useState<string | undefined>();
  const meetupsQuery = useGroupMeetups(selectedGroupId);

  // Default to the member's first group once groups load.
  useEffect(() => {
    const groups = groupsQuery.data;
    if (groups && groups.length > 0 && !groups.some((g) => g.id === selectedGroupId)) {
      setSelectedGroupId(groups[0]!.id);
    }
  }, [groupsQuery.data, selectedGroupId]);

  useLayoutEffect(() => {
    navigation.setOptions({
      headerRight: () => (
        <Pressable onPress={signOut} accessibilityRole="button" accessibilityLabel="Sign out" hitSlop={10} testID="sign-out">
          <Ionicons name="log-out-outline" size={22} color={colors.primary} />
        </Pressable>
      ),
    });
  }, [navigation, signOut]);

  const openMeetup = useCallback(
    (meetup: MeetupSummary) => navigation.navigate('MeetupDetail', { meetupId: meetup.id }),
    [navigation],
  );
  const createMeetup = () => selectedGroupId && navigation.navigate('CreateMeetup', { groupId: selectedGroupId });

  if (groupsQuery.isPending) return <LoadingState message="Loading your groups…" />;
  if (groupsQuery.isError) return <ErrorState message={messageFor(groupsQuery.error)} onRetry={() => groupsQuery.refetch()} />;
  if (groupsQuery.data.length === 0) {
    return <EmptyState title="You’re not in any walking groups yet" message="Once a neighbor adds you to a group, its meetups show up here." />;
  }

  const renderBody = () => {
    if (meetupsQuery.isPending) return <LoadingState message="Loading meetups…" />;
    if (meetupsQuery.isError) return <ErrorState message={messageFor(meetupsQuery.error)} onRetry={() => meetupsQuery.refetch()} />;
    return (
      <FlatList
        data={meetupsQuery.data}
        keyExtractor={(m) => m.id}
        renderItem={({ item }) => <MeetupCard meetup={item} onPress={openMeetup} />}
        contentContainerStyle={meetupsQuery.data.length === 0 ? styles.emptyContainer : styles.list}
        ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />}
        refreshControl={
          <RefreshControl refreshing={meetupsQuery.isRefetching} onRefresh={() => meetupsQuery.refetch()} tintColor={colors.primary} />
        }
        ListEmptyComponent={
          <EmptyState
            title="No meetups yet"
            message="Be the first to plan a walk with your group."
            action={{ label: 'Create a meetup', onPress: createMeetup }}
          />
        }
        testID="meetup-list"
      />
    );
  };

  return (
    <SafeAreaView style={styles.safe} edges={['bottom']}>
      <GroupPicker groups={groupsQuery.data} selectedId={selectedGroupId} onSelect={setSelectedGroupId} />
      <Text style={styles.sectionLabel}>Upcoming & recent · soonest first</Text>
      <View style={styles.body}>{renderBody()}</View>
      <View style={styles.footer}>
        <Button label="New meetup" onPress={createMeetup} disabled={!selectedGroupId} testID="new-meetup-button" />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.background },
  sectionLabel: { ...typography.caption, color: colors.textMuted, paddingHorizontal: spacing.lg, paddingBottom: spacing.xs },
  body: { flex: 1 },
  list: { padding: spacing.lg, paddingTop: spacing.sm },
  emptyContainer: { flexGrow: 1 },
  footer: { padding: spacing.lg, paddingTop: spacing.sm, borderTopWidth: 1, borderTopColor: colors.border, backgroundColor: colors.background },
});

