import type { MeetupDetail } from '@altair/shared';
import { Ionicons } from '@expo/vector-icons';
import { useState } from 'react';
import { Alert, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';
import { messageFor } from '../../../core/api/api-error';
import type { ScreenProps } from '../../../navigation/types';
import { Badge } from '../../../ui/Badge';
import { Banner } from '../../../ui/Banner';
import { Button } from '../../../ui/Button';
import { Card } from '../../../ui/Card';
import { ErrorState, LoadingState } from '../../../ui/StateViews';
import { colors, spacing, typography } from '../../../ui/theme';
import { useCurrentUserId } from '../../auth/AuthProvider';
import { AttendeeList } from '../components/AttendeeList';
import { MeetingPointMap } from '../components/MeetingPointMap';
import { formatCoordinate, formatDayTime, pluralize } from '../format';
import { useCancelMeetup, useMeetupDetail, useRsvp, useWithdrawRsvp } from '../hooks';

type Feedback = { tone: 'success' | 'error'; message: string } | null;

export function MeetupDetailScreen({ route }: ScreenProps<'MeetupDetail'>) {
  const { meetupId, flash } = route.params;
  const query = useMeetupDetail(meetupId);
  const currentUserId = useCurrentUserId();
  const [feedback, setFeedback] = useState<Feedback>(
    flash === 'created' ? { tone: 'success', message: 'Meetup created. Your group can see it now.' } : null,
  );

  if (query.isPending) return <LoadingState message="Loading meetup…" />;
  if (query.isError) return <ErrorState message={messageFor(query.error)} onRetry={() => query.refetch()} />;

  return (
    <ScrollView
      style={styles.screen}
      contentContainerStyle={styles.content}
      refreshControl={<RefreshControl refreshing={query.isRefetching} onRefresh={() => query.refetch()} tintColor={colors.primary} />}
      testID="meetup-detail"
    >
      <MeetupHeader meetup={query.data} />
      {feedback ? <Banner tone={feedback.tone} message={feedback.message} testID="detail-feedback" /> : null}
      <MeetingPointSection meetup={query.data} />
      <RsvpSection meetup={query.data} onFeedback={setFeedback} />
      <Card>
        <Text style={styles.sectionTitle}>
          Who’s going <Text style={styles.muted}>({query.data.attendees.length})</Text>
        </Text>
        <AttendeeList attendees={query.data.attendees} currentUserId={currentUserId} />
      </Card>
      {query.data.viewer.canCancel ? <CancelSection meetup={query.data} onFeedback={setFeedback} /> : null}
    </ScrollView>
  );
}

function MeetupHeader({ meetup }: { meetup: MeetupDetail }) {
  const cancelled = meetup.status === 'cancelled';
  return (
    <View style={styles.header}>
      <View style={styles.badges}>
        {cancelled ? <Badge label="Cancelled" tone="warning" /> : <Badge label="Scheduled" tone="neutral" />}
        {meetup.viewer.isCreator ? <Badge label="Your meetup" tone="accent" /> : null}
      </View>
      <Text style={[styles.title, cancelled && styles.struck]} testID="detail-title">
        {meetup.title}
      </Text>
      <View style={styles.metaRow}>
        <Ionicons name="calendar-outline" size={16} color={colors.textMuted} />
        <Text style={styles.meta}>{formatDayTime(meetup.startsAt)}</Text>
      </View>
      <View style={styles.metaRow}>
        <Ionicons name="person-outline" size={16} color={colors.textMuted} />
        <Text style={styles.meta}>{meetup.viewer.isCreator ? 'You’re hosting' : `Hosted by ${meetup.creator.displayName}`}</Text>
      </View>
      {cancelled ? (
        <Banner tone="warning" message="This meetup was cancelled by its host. It no longer accepts RSVPs." testID="cancelled-banner" />
      ) : null}
    </View>
  );
}

function MeetingPointSection({ meetup }: { meetup: MeetupDetail }) {
  const point = meetup.meetingPoint;
  return (
    <Card>
      <Text style={styles.sectionTitle}>Meeting point</Text>
      <MeetingPointMap point={point} />
      {point.visibility === 'exact' ? (
        <View style={styles.pointInfo} testID="exact-point-info">
          <Text style={styles.placeName}>{point.placeName}</Text>
          <Text style={styles.muted}>
            {formatCoordinate(point.latitude)}, {formatCoordinate(point.longitude)}
          </Text>
        </View>
      ) : (
        <View style={styles.pointInfo} testID="approximate-point-info">
          <Text style={styles.placeName}>Somewhere in the highlighted area</Text>
          <Text style={styles.muted}>
            The exact spot and place name are shared with members who RSVP. This keeps where neighbors gather private to the
            people actually coming.
          </Text>
        </View>
      )}
    </Card>
  );
}

function RsvpSection({ meetup, onFeedback }: { meetup: MeetupDetail; onFeedback: (f: Feedback) => void }) {
  const rsvp = useRsvp(meetup.id);
  const withdraw = useWithdrawRsvp(meetup.id);
  const { viewer } = meetup;

  const doRsvp = () =>
    rsvp.mutate(undefined, {
      onSuccess: () => onFeedback({ tone: 'success', message: 'You’re going! The exact meeting point is now on the map.' }),
      onError: (e) => onFeedback({ tone: 'error', message: messageFor(e) }),
    });
  const doWithdraw = () =>
    withdraw.mutate(undefined, {
      onSuccess: () => onFeedback({ tone: 'success', message: 'Your RSVP was withdrawn.' }),
      onError: (e) => onFeedback({ tone: 'error', message: messageFor(e) }),
    });

  let status: string;
  if (viewer.isAttending) status = 'You’re going.';
  else if (meetup.status === 'cancelled') status = 'This meetup is cancelled.';
  else if (!viewer.canRsvp) status = 'This meetup has started; RSVPs are closed.';
  else status = `${pluralize(meetup.attendeeCount, 'neighbor is', 'neighbors are')} going.`;

  return (
    <Card>
      <Text style={styles.sectionTitle}>Your RSVP</Text>
      <Text style={[styles.body, viewer.isAttending && styles.going]} testID="rsvp-status">
        {status}
      </Text>
      <View style={styles.actions}>
        {viewer.canRsvp ? <Button label="RSVP — I’m going" onPress={doRsvp} loading={rsvp.isPending} testID="rsvp-button" /> : null}
        {viewer.isAttending ? (
          <Button label="Withdraw RSVP" variant="secondary" onPress={doWithdraw} loading={withdraw.isPending} testID="withdraw-button" />
        ) : null}
      </View>
    </Card>
  );
}

function CancelSection({ meetup, onFeedback }: { meetup: MeetupDetail; onFeedback: (f: Feedback) => void }) {
  const cancel = useCancelMeetup(meetup.id);
  const confirm = () =>
    Alert.alert(
      'Cancel this meetup?',
      'Everyone in the group will see it as cancelled. This can’t be undone.',
      [
        { text: 'Keep it', style: 'cancel' },
        {
          text: 'Cancel meetup',
          style: 'destructive',
          onPress: () =>
            cancel.mutate(undefined, {
              onSuccess: () => onFeedback({ tone: 'success', message: 'Meetup cancelled.' }),
              onError: (e) => onFeedback({ tone: 'error', message: messageFor(e) }),
            }),
        },
      ],
      { cancelable: true },
    );
  return (
    <View style={styles.cancelArea}>
      <Button label="Cancel meetup" variant="danger" onPress={confirm} loading={cancel.isPending} testID="cancel-button" />
      <Text style={styles.cancelHint}>Only you, as the host, can cancel.</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: colors.background },
  content: { padding: spacing.lg, gap: spacing.lg, paddingBottom: spacing.xxl },
  header: { gap: spacing.sm },
  badges: { flexDirection: 'row', gap: spacing.xs + 2 },
  title: { ...typography.display, fontSize: 24, color: colors.text },
  struck: { textDecorationLine: 'line-through', color: colors.textMuted },
  metaRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm },
  meta: { ...typography.body, color: colors.textMuted },
  sectionTitle: { ...typography.heading, color: colors.text, marginBottom: spacing.md },
  pointInfo: { marginTop: spacing.md, gap: 2 },
  placeName: { ...typography.heading, color: colors.text },
  muted: { ...typography.caption, color: colors.textMuted, fontSize: 13, lineHeight: 18 },
  body: { ...typography.body, color: colors.text },
  going: { color: colors.success, fontWeight: '600' },
  actions: { gap: spacing.sm, marginTop: spacing.md },
  cancelArea: { gap: spacing.sm, alignItems: 'stretch' },
  cancelHint: { ...typography.caption, color: colors.textMuted, textAlign: 'center' },
});

import type { MeetupSummary } from '@altair/shared';
import { Ionicons } from '@expo/vector-icons';
import { useCallback, useEffect, useLayoutEffect, useState } from 'react';
import { FlatList, Pressable, RefreshControl, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { messageFor } from '../../../core/api/api-error';
import type { ScreenProps } from '../../../navigation/types';
import { Button } from '../../../ui/Button';
import { EmptyState, ErrorState, LoadingState } from '../../../ui/StateViews';
import { colors, spacing, typography } from '../../../ui/theme';
import { useAuth } from '../../auth/AuthProvider';
import { GroupPicker } from '../../groups/GroupPicker';
import { useMyGroups } from '../../groups/hooks';
import { MeetupCard } from '../components/MeetupCard';
import { useGroupMeetups } from '../hooks';

export function MeetupListScreen({ navigation }: ScreenProps<'Meetups'>) {
  const { signOut } = useAuth();
  const groupsQuery = useMyGroups();
  const [selectedGroupId, setSelectedGroupId] = useState<string | undefined>();
  const meetupsQuery = useGroupMeetups(selectedGroupId);

  // Default to the member's first group once groups load.
  useEffect(() => {
    const groups = groupsQuery.data;
    if (groups && groups.length > 0 && !groups.some((g) => g.id === selectedGroupId)) {
      setSelectedGroupId(groups[0]!.id);
    }
  }, [groupsQuery.data, selectedGroupId]);

  useLayoutEffect(() => {
    navigation.setOptions({
      headerRight: () => (
        <Pressable onPress={signOut} accessibilityRole="button" accessibilityLabel="Sign out" hitSlop={10} testID="sign-out">
          <Ionicons name="log-out-outline" size={22} color={colors.primary} />
        </Pressable>
      ),
    });
  }, [navigation, signOut]);

  const openMeetup = useCallback(
    (meetup: MeetupSummary) => navigation.navigate('MeetupDetail', { meetupId: meetup.id }),
    [navigation],
  );
  const createMeetup = () => selectedGroupId && navigation.navigate('CreateMeetup', { groupId: selectedGroupId });

  if (groupsQuery.isPending) return <LoadingState message="Loading your groups…" />;
  if (groupsQuery.isError) return <ErrorState message={messageFor(groupsQuery.error)} onRetry={() => groupsQuery.refetch()} />;
  if (groupsQuery.data.length === 0) {
    return <EmptyState title="You’re not in any walking groups yet" message="Once a neighbor adds you to a group, its meetups show up here." />;
  }

  const renderBody = () => {
    if (meetupsQuery.isPending) return <LoadingState message="Loading meetups…" />;
    if (meetupsQuery.isError) return <ErrorState message={messageFor(meetupsQuery.error)} onRetry={() => meetupsQuery.refetch()} />;
    return (
      <FlatList
        data={meetupsQuery.data}
        keyExtractor={(m) => m.id}
        renderItem={({ item }) => <MeetupCard meetup={item} onPress={openMeetup} />}
        contentContainerStyle={meetupsQuery.data.length === 0 ? styles.emptyContainer : styles.list}
        ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />}
        refreshControl={
          <RefreshControl refreshing={meetupsQuery.isRefetching} onRefresh={() => meetupsQuery.refetch()} tintColor={colors.primary} />
        }
        ListEmptyComponent={
          <EmptyState
            title="No meetups yet"
            message="Be the first to plan a walk with your group."
            action={{ label: 'Create a meetup', onPress: createMeetup }}
          />
        }
        testID="meetup-list"
      />
    );
  };

  return (
    <SafeAreaView style={styles.safe} edges={['bottom']}>
      <GroupPicker groups={groupsQuery.data} selectedId={selectedGroupId} onSelect={setSelectedGroupId} />
      <Text style={styles.sectionLabel}>Upcoming & recent · soonest first</Text>
      <View style={styles.body}>{renderBody()}</View>
      <View style={styles.footer}>
        <Button label="New meetup" onPress={createMeetup} disabled={!selectedGroupId} testID="new-meetup-button" />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.background },
  sectionLabel: { ...typography.caption, color: colors.textMuted, paddingHorizontal: spacing.lg, paddingBottom: spacing.xs },
  body: { flex: 1 },
  list: { padding: spacing.lg, paddingTop: spacing.sm },
  emptyContainer: { flexGrow: 1 },
  footer: { padding: spacing.lg, paddingTop: spacing.sm, borderTopWidth: 1, borderTopColor: colors.border, backgroundColor: colors.background },
});

