import type { MeetupDetail, MeetupSummary } from '@altair/shared';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { render } from '@testing-library/react-native';
import type { ReactElement } from 'react';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import type { AppServices, AuthGateway } from '../src/core/ports';
import { ServicesProvider } from '../src/core/services';
import { AuthProvider } from '../src/features/auth/AuthProvider';

export const SAM = 'a1000000-0000-4000-8000-000000000003';
export const AVERY = 'a1000000-0000-4000-8000-000000000001';
export const MAPLE = 'b2000000-0000-4000-8000-000000000001';
export const SATURDAY = 'c3000000-0000-4000-8000-000000000001';

export function fakeAuth(userId = SAM): AuthGateway {
  const session = { userId, email: 'sam@example.test' };
  return {
    currentSession: async () => session,
    signIn: async () => session,
    signOut: async () => undefined,
    onSessionChange: () => () => undefined,
    accessToken: async () => 'token',
  };
}

export function fakeServices(overrides: Partial<{ [K in keyof AppServices]: Partial<AppServices[K]> }> = {}, userId = SAM): AppServices {
  const reject = () => Promise.reject(new Error('not stubbed'));
  return {
    auth: { ...fakeAuth(userId), ...overrides.auth },
    groups: { listMine: reject, ...overrides.groups },
    meetups: {
      listForGroup: reject,
      get: reject,
      create: reject,
      cancel: reject,
      rsvp: reject,
      withdraw: reject,
      ...overrides.meetups,
    },
  };
}

export function renderWithServices(ui: ReactElement, services: AppServices) {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false }, mutations: { retry: false } } });
  return render(
    <SafeAreaProvider initialMetrics={{ frame: { x: 0, y: 0, width: 390, height: 844 }, insets: { top: 0, left: 0, right: 0, bottom: 0 } }}>
      <QueryClientProvider client={queryClient}>
        <ServicesProvider services={services}>
          <AuthProvider>{ui}</AuthProvider>
        </ServicesProvider>
      </QueryClientProvider>
    </SafeAreaProvider>,
  );
}

export function fakeNavigation() {
  return { navigate: jest.fn(), replace: jest.fn(), setOptions: jest.fn(), goBack: jest.fn() } as never;
}

const approximate = {
  visibility: 'approximate' as const,
  label: 'Approximate area · RSVP to see the exact meeting point',
  centerLatitude: 40.0139,
  centerLongitude: -99.9861,
  radiusMeters: 400,
};

const exact = {
  visibility: 'exact' as const,
  placeName: 'North gate, Linden Park',
  latitude: 40.012046,
  longitude: -99.984517,
};

export function summary(overrides: Partial<MeetupSummary> = {}): MeetupSummary {
  return {
    id: SATURDAY,
    groupId: MAPLE,
    title: 'Saturday morning loop',
    startsAt: '2099-11-07T15:00:00.000Z',
    status: 'scheduled',
    cancelledAt: null,
    creator: { id: AVERY, displayName: 'Avery Lin' },
    attendeeCount: 2,
    viewer: { isCreator: false, isAttending: false, canRsvp: true, canCancel: false },
    meetingPoint: approximate,
    ...overrides,
  };
}

export function detail(overrides: Partial<MeetupDetail> = {}): MeetupDetail {
  return {
    ...summary(),
    attendees: [
      { userId: 'a1000000-0000-4000-8000-000000000002', displayName: 'Jordan Price', rsvpAt: '2026-10-29T10:00:00.000Z' },
      { userId: 'a1000000-0000-4000-8000-000000000004', displayName: 'Riley Chen', rsvpAt: '2026-10-29T10:01:00.000Z' },
    ],
    ...overrides,
  };
}

export const points = { approximate, exact };

import { render, screen } from '@testing-library/react-native';
import { MeetingPointMap, regionFor } from '../src/features/meetups/components/MeetingPointMap';
import { points } from './helpers';

describe('MeetingPointMap', () => {
  it('draws the approximate area as a circle and no marker', () => {
    render(<MeetingPointMap point={points.approximate} />);
    const circle = screen.getByTestId('map-area');
    expect(circle.props.radius).toBe(400);
    expect(circle.props.center).toEqual({ latitude: 40.0139, longitude: -99.9861 });
    expect(screen.queryByTestId('map-marker')).toBeNull();
    expect(screen.getByText('Approximate area · ~400 m')).toBeTruthy();
  });

  it('draws the exact point as a marker titled with the place name', () => {
    render(<MeetingPointMap point={points.exact} />);
    const marker = screen.getByTestId('map-marker');
    expect(marker.props.coordinate).toEqual({ latitude: 40.012046, longitude: -99.984517 });
    expect(marker.props.title).toBe('North gate, Linden Park');
    expect(screen.queryByTestId('map-area')).toBeNull();
  });

  it('frames the whole circle for the approximate view', () => {
    const region = regionFor(points.approximate);
    const radiusInDegrees = 400 / 111_320;
    expect(region.latitudeDelta).toBeGreaterThan(2 * radiusInDegrees);
    expect(region.latitude).toBe(40.0139);
  });
});

import { fireEvent, screen, waitFor } from '@testing-library/react-native';
import { Alert } from 'react-native';
import { MeetupDetailScreen } from '../src/features/meetups/screens/MeetupDetailScreen';
import { AVERY, SAM, SATURDAY, detail, fakeNavigation, fakeServices, points, renderWithServices } from './helpers';

const renderDetail = (services: ReturnType<typeof fakeServices>) =>
  renderWithServices(
    <MeetupDetailScreen route={{ key: 'd', name: 'MeetupDetail', params: { meetupId: SATURDAY } }} navigation={fakeNavigation()} />,
    services,
  );

describe('MeetupDetailScreen', () => {
  it('shows a loading state, then title, attendees and the approximate area for a member without RSVP', async () => {
    renderDetail(fakeServices({ meetups: { get: async () => detail() } }));
    expect(screen.getByTestId('state-loading')).toBeTruthy();
    expect(await screen.findByText('Saturday morning loop')).toBeTruthy();
    expect(screen.getByText('Jordan Price')).toBeTruthy();
    expect(screen.getByText('Riley Chen')).toBeTruthy();
    expect(screen.getByTestId('map-approximate')).toBeTruthy();
    expect(screen.queryByText('North gate, Linden Park')).toBeNull();
    expect(screen.queryByTestId('cancel-button')).toBeNull();
  });

  it('after RSVP, the map switches to the exact point from the server response', async () => {
    const rsvp = jest.fn(async () =>
      detail({
        meetingPoint: points.exact,
        attendeeCount: 3,
        viewer: { isCreator: false, isAttending: true, canRsvp: false, canCancel: false },
        attendees: [...detail().attendees, { userId: SAM, displayName: 'Sam Okafor', rsvpAt: '2026-10-29T11:00:00.000Z' }],
      }),
    );
    renderDetail(fakeServices({ meetups: { get: async () => detail(), rsvp } }));

    fireEvent.press(await screen.findByTestId('rsvp-button'));

    await waitFor(() => expect(screen.getByTestId('map-exact')).toBeTruthy());
    expect(rsvp).toHaveBeenCalledWith(SATURDAY);
    expect(screen.getByTestId('exact-point-info')).toBeTruthy();
    expect(screen.getAllByText('North gate, Linden Park').length).toBeGreaterThan(0);
    expect(screen.getByText(/Sam Okafor/)).toBeTruthy();
    expect(screen.getByTestId('withdraw-button')).toBeTruthy();
    expect(screen.queryByTestId('rsvp-button')).toBeNull();
  });

  it('shows the cancel action only to the creator, behind a confirmation', async () => {
    const alert = jest.spyOn(Alert, 'alert').mockImplementation(() => undefined);
    const creatorView = detail({
      meetingPoint: points.exact,
      viewer: { isCreator: true, isAttending: false, canRsvp: true, canCancel: true },
    });
    renderDetail(fakeServices({ meetups: { get: async () => creatorView } }, AVERY));
    fireEvent.press(await screen.findByTestId('cancel-button'));
    expect(alert).toHaveBeenCalledWith('Cancel this meetup?', expect.any(String), expect.any(Array), expect.anything());
    alert.mockRestore();
  });

  it('marks a cancelled meetup and offers no RSVP', async () => {
    renderDetail(
      fakeServices({
        meetups: {
          get: async () =>
            detail({ status: 'cancelled', cancelledAt: '2026-10-29T12:00:00.000Z', viewer: { isCreator: false, isAttending: false, canRsvp: false, canCancel: false } }),
        },
      }),
    );
    expect(await screen.findByTestId('cancelled-banner')).toBeTruthy();
    expect(screen.queryByTestId('rsvp-button')).toBeNull();
    expect(screen.getByTestId('rsvp-status').props.children).toBe('This meetup is cancelled.');
  });

  it('shows an error state with retry when the meetup cannot be loaded', async () => {
    renderDetail(fakeServices({ meetups: { get: async () => Promise.reject(new Error('Meetup not found')) } }));
    expect(await screen.findByTestId('state-error')).toBeTruthy();
    expect(screen.getByText('Meetup not found')).toBeTruthy();
  });

  it('surfaces a server rejection of an RSVP', async () => {
    const { ApiError } = jest.requireActual('../src/core/api/api-error');
    renderDetail(
      fakeServices({
        meetups: {
          get: async () => detail(),
          rsvp: async () => Promise.reject(new ApiError('MEETUP_STARTED', 'This meetup has already started and no longer accepts RSVPs', 409)),
        },
      }),
    );
    fireEvent.press(await screen.findByTestId('rsvp-button'));
    expect(await screen.findByText('This meetup has already started and no longer accepts RSVPs')).toBeTruthy();
  });
});

import { fireEvent, screen } from '@testing-library/react-native';
import { MeetupListScreen } from '../src/features/meetups/screens/MeetupListScreen';
import { MAPLE, fakeNavigation, fakeServices, renderWithServices, summary } from './helpers';

const RIVERSIDE = 'b2000000-0000-4000-8000-000000000002';
const groups = [
  { id: MAPLE, name: 'Maple Street Walkers' },
  { id: RIVERSIDE, name: 'Riverside Loop Walkers' },
];

const renderList = (services: ReturnType<typeof fakeServices>, navigation = fakeNavigation()) =>
  renderWithServices(<MeetupListScreen route={{ key: 'm', name: 'Meetups' } as never} navigation={navigation} />, services);

describe('MeetupListScreen', () => {
  it('loads groups, picks the first, and lists its meetups including cancelled ones', async () => {
    const listForGroup = jest.fn(async () => [
      summary(),
      summary({ id: 'c3000000-0000-4000-8000-000000000002', title: 'Weeknight short walk', status: 'cancelled', cancelledAt: '2026-10-29T12:00:00.000Z' }),
    ]);
    renderList(fakeServices({ groups: { listMine: async () => groups }, meetups: { listForGroup } }));

    expect(screen.getByTestId('state-loading')).toBeTruthy();
    expect(await screen.findByText('Saturday morning loop')).toBeTruthy();
    expect(screen.getByText('Weeknight short walk')).toBeTruthy();
    expect(screen.getByText('Cancelled')).toBeTruthy();
    expect(listForGroup).toHaveBeenCalledWith(MAPLE);
  });

  it('switches group when another chip is pressed', async () => {
    const listForGroup = jest.fn(async () => [summary()]);
    renderList(fakeServices({ groups: { listMine: async () => groups }, meetups: { listForGroup } }));
    fireEvent.press(await screen.findByTestId(`group-chip-${RIVERSIDE}`));
    await screen.findByText('Saturday morning loop');
    expect(listForGroup).toHaveBeenCalledWith(RIVERSIDE);
  });

  it('shows the empty state with a create action', async () => {
    const navigation = fakeNavigation() as unknown as { navigate: jest.Mock };
