    const a = { latitude: 40, longitude: -100 };
    const b = { latitude: 41, longitude: -98 };
    expect(interpolate(a, b, 0.25)).toEqual({ latitude: 40.25, longitude: -99.5 });
    expect(interpolate(a, b, -1)).toEqual(a);
    expect(interpolate(a, b, 2)).toEqual(b);
  });

