import {
  cullToViewport,
  interpolate,
  PositionTracker,
  type TrackerOptions,
} from '../src/features/live-walk/engine';

const options: TrackerOptions = { renderDelayMs: 1000, staleAfterMs: 3000, dropAfterMs: 10000, bufferSize: 4 };
const msg = (seq: number, ts: number, latitude = 40, longitude = -100, participantId = 'walker-01') => ({
  participantId,
  latitude,
  longitude,
  ts,
  seq,
});

