// Finds cycles among relative imports in the given source folders (no dependencies).
import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

const roots = process.argv.slice(2).map((r) => resolve(r));
const files = [];
const walk = (d) => {
  for (const n of readdirSync(d)) {
    const p = join(d, n);
    if (statSync(p).isDirectory()) walk(p);
    else if (/\.(ts|tsx)$/.test(n)) files.push(p);
  }
};
roots.forEach(walk);

const resolveImport = (from, spec) => {
  const base = resolve(dirname(from), spec);
  for (const c of [base, `${base}.ts`, `${base}.tsx`, join(base, 'index.ts')]) {
    if (existsSync(c) && statSync(c).isFile()) return c;
  }
  return null;
};

const graph = new Map();
for (const f of files) {
  const src = readFileSync(f, 'utf8');
  const deps = [];
  for (const m of src.matchAll(/^\s*(?:import|export)\s[^'"]*?from\s+['"](\.[^'"]+)['"]/gm)) {
    // type-only imports cannot create runtime cycles, but report them too
    const target = resolveImport(f, m[1]);
    if (target) deps.push(target);
  }
  graph.set(f, deps);
}

const cycles = [];
const state = new Map();
const stack = [];
const visit = (n) => {
  state.set(n, 'open');
  stack.push(n);
  for (const d of graph.get(n) ?? []) {
    if (state.get(d) === 'open') cycles.push(stack.slice(stack.indexOf(d)).concat(d));
    else if (!state.has(d)) visit(d);
  }
  stack.pop();
  state.set(n, 'done');
};
for (const f of files) if (!state.has(f)) visit(f);

console.log(`${files.length} files scanned, ${cycles.length} cycle(s)`);
for (const c of cycles) console.log(' - ' + c.map((p) => p.replace(/^.*?(server|mobile|packages)/, '$1')).join(' -> '));

