// Tiny adb UI driver for the E2E run (emulator-5554 only).
//   node ui.mjs texts
//   node ui.mjs wait "<label>" [seconds]
//   node ui.mjs tap "<label>" [index]
//   node ui.mjs type "<text>"
//   node ui.mjs clear            (select-all + delete in focused field)
//   node ui.mjs shot <name>
//   node ui.mjs key <BACK|ENTER|...>
//   node ui.mjs swipe up|down
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const ADB = `${process.env.LOCALAPPDATA}\\Android\\Sdk\\platform-tools\\adb.exe`;
const SHOTS = 'C:/Users/zuhoor/AppData/Local/Temp/claude/d--altar/55658eaf-438e-4571-8d49-df4b72281969/scratchpad';
const adb = (...args) => execFileSync(ADB, ['-s', 'emulator-5554', ...args], { encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function nodes() {
  adb('shell', 'uiautomator', 'dump', '/sdcard/ui.xml');
  const xml = adb('shell', 'cat', '/sdcard/ui.xml').toString('utf8');
  const out = [];
  for (const m of xml.matchAll(/<node [^>]*>/g)) {
    const attr = (n) => (m[0].match(new RegExp(`${n}="([^"]*)"`)) ?? [])[1] ?? '';
    const b = attr('bounds').match(/\[(\d+),(\d+)\]\[(\d+),(\d+)\]/);
    if (!b) continue;
    const [x1, y1, x2, y2] = b.slice(1).map(Number);
    const label = (attr('text') || attr('content-desc')).replace(/&amp;/g, '&').replace(/&#10;/g, ' ').replace(/&quot;/g, '"').replace(/&apos;/g, "'");
    out.push({ label, x: Math.round((x1 + x2) / 2), y: Math.round((y1 + y2) / 2), clickable: attr('clickable') === 'true', area: (x2 - x1) * (y2 - y1) });
  }
  return out;
}

function find(label, list) {
  const exact = list.filter((n) => n.label === label);
  if (exact.length) return exact;
  return list.filter((n) => n.label.toLowerCase().includes(label.toLowerCase()));
}

const [cmd, a1, a2] = process.argv.slice(2);
if (cmd === 'texts') {
  for (const n of nodes()) if (n.label) console.log(`${n.clickable ? '*' : ' '} ${n.label}  @${n.x},${n.y}`);
} else if (cmd === 'wait') {
  const deadline = Date.now() + Number(a2 ?? 30) * 1000;
  for (;;) {
    const hit = find(a1, nodes());
    if (hit.length) { console.log(`found "${a1}"`); break; }
    if (Date.now() > deadline) { console.log(`TIMEOUT waiting for "${a1}"`); process.exit(2); }
    await sleep(1500);
  }
} else if (cmd === 'tap') {
  const hits = find(a1, nodes());
  const n = hits[Number(a2 ?? 0)];
  if (!n) { console.log(`NOT FOUND "${a1}"`); process.exit(2); }
  adb('shell', 'input', 'tap', String(n.x), String(n.y));
  console.log(`tapped "${n.label}" @${n.x},${n.y}`);
} else if (cmd === 'type') {
  adb('shell', 'input', 'text', a1.replace(/ /g, '%s').replace(/([()&;<>|'"])/g, '\\$1'));
  console.log(`typed ${a1.length} chars`);
} else if (cmd === 'clear') {
  adb('shell', 'input', 'keycombination', '113', '29'); // CTRL+A
  adb('shell', 'input', 'keyevent', 'KEYCODE_DEL');
  console.log('cleared');
} else if (cmd === 'shot') {
  writeFileSync(`${SHOTS}/e2e-${a1}.png`, adb('exec-out', 'screencap', '-p'));
  console.log(`${SHOTS}/e2e-${a1}.png`);
} else if (cmd === 'key') {
  adb('shell', 'input', 'keyevent', `KEYCODE_${a1}`);
  console.log(`key ${a1}`);
} else if (cmd === 'swipe') {
  const [y1, y2] = a1 === 'up' ? [1800, 700] : [700, 1800];
  adb('shell', 'input', 'swipe', '540', String(y1), '540', String(y2), '300');
  console.log(`swiped ${a1}`);
}

