// Read-mostly probe of the hosted DB: current state of the Saturday loop, and
// whether a NON-creator can update it as altair_api_writer (always rolled back).
import pg from 'pg';
import { loadDotEnv, readServerEnv } from '../../../../../../../../altar/server/src/config/env';

loadDotEnv();
const client = new pg.Client({ connectionString: readServerEnv().DATABASE_URL });
await client.connect();
const SAT = 'c3000000-0000-4000-8000-000000000001';
const people: Record<string, string> = {
  avery: 'a1000000-0000-4000-8000-000000000001',
  jordan: 'a1000000-0000-4000-8000-000000000002',
  sam: 'a1000000-0000-4000-8000-000000000003',
  riley: 'a1000000-0000-4000-8000-000000000004',
  quinn: 'a1000000-0000-4000-8000-000000000008',
  taylor: 'a1000000-0000-4000-8000-000000000007',
};
try {
  const state = await client.query(
    `select m.title, m.created_by, m.status, m.starts_at, p.place_name, p.latitude, p.longitude
       from public.meetups m join public.meetup_meeting_points p on p.meetup_id = m.id where m.id = $1`,
    [SAT],
  );
  console.log('current Saturday loop:', state.rows[0]);
  const policies = await client.query(
    `select tablename, policyname, cmd, roles::text from pg_policies
      where schemaname = 'public' and cmd in ('UPDATE','ALL') order by 1, 2`,
  );
  console.log('UPDATE policies:', policies.rows);

  for (const [name, id] of Object.entries(people)) {
    await client.query('begin');
    await client.query('set local role altair_api_writer');
    await client.query(`select set_config('request.jwt.claims', $1, true)`, [JSON.stringify({ sub: id })]);
    const res: Record<string, string | number> = {};
    for (const [label, sql] of [
      ['title', `update public.meetups set title = 'probe' where id = $1`],
      ['point', `update public.meetup_meeting_points set place_name = 'probe' where meetup_id = $1`],
    ] as const) {
      await client.query('savepoint s');
      try {
        res[label] = (await client.query(sql, [SAT])).rowCount ?? 0;
      } catch (e) {
        res[label] = (e as { code?: string }).code ?? 'error';
        await client.query('rollback to savepoint s');
      }
    }
    await client.query('rollback');
    console.log(`${name.padEnd(7)} rows changed -> title: ${res.title}, meeting point: ${res.point}`);
  }
} finally {
  await client.end();
}

