// Calls the running API as real seed users (fixture accounts). Prints status codes and
// error codes only. Usage: node api-probe.mjs
process.loadEnvFile('D:/altar/.env');
const { SUPABASE_URL: url, SUPABASE_ANON_KEY: key } = process.env;
const API = 'http://localhost:4000';
const SAT = 'c3000000-0000-4000-8000-000000000001';
const MAPLE = 'b2000000-0000-4000-8000-000000000001';

async function token(name) {
  const r = await fetch(`${url}/auth/v1/token?grant_type=password`, {
    method: 'POST',
    headers: { apikey: key, 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: `${name}@example.test`, password: 'altair-fixture-pass' }),
  });
  return (await r.json()).access_token;
}
async function call(name, method, path, body) {
  const r = await fetch(`${API}${path}`, {
    method,
    headers: { Authorization: `Bearer ${await token(name)}`, ...(body ? { 'Content-Type': 'application/json' } : {}) },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  const json = await r.json().catch(() => ({}));
  return { status: r.status, code: json.error?.code, body: json };
}
async function rest(name, path) {
  const r = await fetch(`${url}/rest/v1/${path}`, { headers: { apikey: key, Authorization: `Bearer ${await token(name)}` } });
  return { status: r.status, body: await r.json() };
}

const sam = await call('sam', 'PUT', `/v1/meetups/${SAT}/rsvp`);
console.log(`sam RSVP to cancelled Saturday           -> ${sam.status} ${sam.code}`);
const jordan = await call('jordan', 'DELETE', `/v1/meetups/${SAT}/rsvp`);
console.log(`jordan withdraws after cancellation      -> ${jordan.status}, attendees now ${jordan.body.meetup?.attendeeCount}`);
const edit = await call('avery', 'PATCH', `/v1/meetups/${SAT}`, { title: 'reopen?' });
console.log(`avery edits her cancelled meetup         -> ${edit.status} ${edit.code}`);

const tGroups = await call('taylor', 'GET', '/v1/me/groups');
console.log(`taylor my groups                         -> ${tGroups.status} ${JSON.stringify(tGroups.body)}`);
for (const [label, path] of [
  ['detail', `/v1/meetups/${SAT}`],
  ['attendees', `/v1/meetups/${SAT}/attendees`],
  ['map', `/v1/meetups/${SAT}/map`],
  ['group list', `/v1/groups/${MAPLE}/meetups`],
]) {
  const r = await call('taylor', 'GET', path);
  console.log(`taylor API ${label.padEnd(29)}-> ${r.status} ${JSON.stringify(r.body)}`);
}
for (const table of ['meetups?select=*', 'rsvps?select=*', 'meetup_meeting_points?select=*', 'users?select=id,display_name']) {
  const r = await rest('taylor', table);
  console.log(`taylor PostgREST ${table.padEnd(26)}-> ${r.status} ${JSON.stringify(r.body)}`);
}

