// Temporary probe: can each persona join the private live channel of Saturday loop?
import { liveWalkTopic } from '@altair/shared';
import { createClient } from '@supabase/supabase-js';
import { loadDotEnv, readServerEnv } from '../src/config/env';

loadDotEnv();
const env = readServerEnv();
const topic = liveWalkTopic('c3000000-0000-4000-8000-000000000001');

for (const name of ['jordan', 'avery', 'sam', 'quinn', 'taylor']) {
  const client = createClient(env.SUPABASE_URL, env.SUPABASE_ANON_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data } = await client.auth.signInWithPassword({
    email: `${name}@example.test`,
    password: 'altair-fixture-pass',
  });
  await client.realtime.setAuth(data.session!.access_token);
  const status = await new Promise<string>((resolve) => {
    const timer = setTimeout(() => resolve('TIMEOUT'), 15000);
    client.channel(topic, { config: { private: true } }).subscribe((s, err) => {
      if (s === 'SUBSCRIBED' || s === 'CHANNEL_ERROR' || s === 'TIMED_OUT') {
        clearTimeout(timer);
        resolve(err ? `${s} (${err.message})` : s);
      }
    });
  });
  console.log(`${name.padEnd(7)} -> ${status}`);
  await client.removeAllChannels();
}
process.exit(0);

