// Builds docs/Altair_Meetups_User_Guide.docx
const fs = require('fs');
const path = require('path');
const {
  AlignmentType, BorderStyle, Document, Footer, HeadingLevel, ImageRun, LevelFormat, Packer,
  PageBreak, PageNumber, Paragraph, PositionalTab, PositionalTabAlignment, PositionalTabLeader,
  PositionalTabRelativeTo, ShadingType, Table, TableCell, TableLayoutType, TableOfContents,
  TableRow, TextRun, VerticalAlign, WidthType,
} = require('docx');

const IMG = path.join(__dirname, 'img');
const OUT = 'D:/altar/docs/Altair_Meetups_User_Guide.docx';

// ---------------------------------------------------------------- palette
const C = {
  green: '005B43', text: '17231F', muted: '63706C', mint: 'E2F2EA', zebra: 'F4F8F5',
  rule: 'D6DDD8', warnBg: 'FFF4E5', warnBar: 'B26A00', white: 'FFFFFF',
};
const FONT = 'Calibri';
const CONTENT = 9306; // A4 width 11906 - 2 x 1300 margins (DXA)

// ---------------------------------------------------------------- text helpers
/** "Plain **bold** and `code`" -> TextRuns */
function runs(text, base = {}) {
  const out = [];
  for (const part of String(text).split(/(\*\*[^*]+\*\*|`[^`]+`)/g)) {
    if (!part) continue;
    if (part.startsWith('**')) out.push(new TextRun({ ...base, text: part.slice(2, -2), bold: true }));
    else if (part.startsWith('`'))
      out.push(new TextRun({ ...base, text: part.slice(1, -1), font: 'Consolas', size: 19, color: C.green }));
    else out.push(new TextRun({ ...base, text: part }));
  }
  return out;
}
const p = (text, opts = {}) =>
  new Paragraph({ children: runs(text, opts.run), spacing: { after: 120, line: 276 }, ...opts.para });
const h1 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)], pageBreakBefore: true });
const h1Same = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
const h2 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
const bullets = (items) =>
  items.map((t) => new Paragraph({ children: runs(t), numbering: { reference: 'bullets', level: 0 }, spacing: { after: 60, line: 276 } }));
let stepInstance = 0;
const steps = (items) => {
  stepInstance += 1;
  return items.map(
    (t) => new Paragraph({ children: runs(t), numbering: { reference: 'steps', level: 0, instance: stepInstance }, spacing: { after: 80, line: 276 } }),
  );
};
const code = (lines) =>
  lines.map(
    (l, i) =>
      new Paragraph({
        children: [new TextRun({ text: l, font: 'Consolas', size: 19, color: C.text })],
        shading: { type: ShadingType.CLEAR, color: 'auto', fill: 'F2F4F3' },
        spacing: { before: i === 0 ? 60 : 0, after: i === lines.length - 1 ? 160 : 0 },
        indent: { left: 200, right: 200 },
      }),
  );

// ---------------------------------------------------------------- boxes and tables
const none = { style: BorderStyle.NONE, size: 0, color: C.white };
const noBorders = { top: none, bottom: none, left: none, right: none, insideHorizontal: none, insideVertical: none };

function callout(title, body, kind = 'info') {
  const bar = kind === 'warn' ? C.warnBar : C.green;
  const fill = kind === 'warn' ? C.warnBg : C.mint;
  const content = [
    new Paragraph({ children: [new TextRun({ text: title, bold: true, color: bar })], spacing: { after: 60 } }),
    ...[].concat(body).map((b) => new Paragraph({ children: runs(b), spacing: { after: 60, line: 264 } })),
  ];
  return [
    new Table({
      width: { size: CONTENT, type: WidthType.DXA },
      columnWidths: [CONTENT],
      layout: TableLayoutType.FIXED,
      borders: noBorders,
      rows: [
        new TableRow({
          children: [
            new TableCell({
              width: { size: CONTENT, type: WidthType.DXA },
              shading: { type: ShadingType.CLEAR, color: 'auto', fill },
              borders: { top: none, bottom: none, right: none, left: { style: BorderStyle.SINGLE, size: 24, color: bar } },
              margins: { top: 120, bottom: 100, left: 220, right: 220 },
              children: content,
            }),
          ],
        }),
      ],
    }),
    new Paragraph({ children: [], spacing: { after: 80 } }),
  ];
}

function table(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const border = { style: BorderStyle.SINGLE, size: 4, color: C.rule };
  const borders = { top: border, bottom: border, left: border, right: border };
  const cell = (text, w, header, zebra) =>
    new TableCell({
      width: { size: w, type: WidthType.DXA },
      borders,
      verticalAlign: VerticalAlign.CENTER,
      shading: header
        ? { type: ShadingType.CLEAR, color: 'auto', fill: C.green }
        : zebra
          ? { type: ShadingType.CLEAR, color: 'auto', fill: C.zebra }
          : undefined,
      margins: { top: 70, bottom: 70, left: 110, right: 110 },
      children: [
        new Paragraph({
          children: runs(text, header ? { bold: true, color: C.white, size: 20 } : { size: 20 }),
          spacing: { after: 0, line: 252 },
        }),
      ],
    });
  return [
    new Table({
      width: { size: total, type: WidthType.DXA },
      columnWidths: widths,
      layout: TableLayoutType.FIXED,
      rows: [
        new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, widths[i], true)) }),
        ...rows.map((r, ri) => new TableRow({ cantSplit: true, children: r.map((t, i) => cell(t, widths[i], false, ri % 2 === 1)) })),
      ],
    }),
    new Paragraph({ children: [], spacing: { after: 120 } }),
  ];
}

// ---------------------------------------------------------------- figures
let figureNo = 0;
const SHOT_W = 205; // px; screenshots are 544 x 1204
const SHOT_H = Math.round((SHOT_W * 1204) / 544);
function shot(name, caption) {
  figureNo += 1;
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      keepNext: true,
      spacing: { before: 60, after: 60 },
      children: [
        new ImageRun({
          type: 'jpg',
          data: fs.readFileSync(path.join(IMG, `${name}.jpg`)),
          transformation: { width: SHOT_W, height: SHOT_H },
          altText: { title: caption, description: caption, name },
        }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 60 },
      children: [new TextRun({ text: `Figure ${figureNo}. ${caption}`, italics: true, size: 18, color: C.muted })],
    }),
  ];
}
function figures(items) {
  const w = Math.floor(CONTENT / items.length);
  const widths = items.map(() => w);
  widths[widths.length - 1] = CONTENT - w * (items.length - 1);
  return [
    new Table({
      width: { size: CONTENT, type: WidthType.DXA },
      columnWidths: widths,
      layout: TableLayoutType.FIXED,
      borders: noBorders,
      rows: [
        new TableRow({
          cantSplit: true,
          children: items.map(
            ([name, caption], i) =>
              new TableCell({ width: { size: widths[i], type: WidthType.DXA }, borders: { top: none, bottom: none, left: none, right: none }, children: shot(name, caption) }),
          ),
        }),
      ],
    }),
    new Paragraph({ children: [], spacing: { after: 100 } }),
  ];
}

