  // 14
  h1('14. For evaluators: running Altair'),
  p('This section summarizes the README in the repository. It needs Node.js 22.13 or later and a hosted Supabase project; Docker is not required.'),
  h2('1. Install'),
  ...code(['git clone <repository> altair && cd altair', 'npm ci']),
  h2('2. Configure'),
  p('Copy `.env.example` to `.env` and `mobile/.env.example` to `mobile/.env`, then fill them in from your Supabase project. Use the **publishable (anon) key**, never the service-role key, and the **Session pooler** connection string with your real database password.'),
  h2('3. Set up the database'),
  ...code([
    'npm run db:inspect     # read-only check of the database',
    'npm run db:push:dry    # preview the migrations',
    'npm run db:push        # apply the migrations',
    'npm run db:seed        # demo accounts, groups and reference meetups',
  ]),
  ...callout('Windows PowerShell', ['Use `npm run db:push:dry` for the preview. Do not use `npm run db:push -- --dry-run`: PowerShell drops the `--`, so the migrations would really be applied.'], 'warn'),
  h2('4. Start the server and the app'),
  ...code(['npm run server         # API on http://localhost:4000', 'npm run mobile         # then press "a" for the Android emulator']),
  ...table(
    ['Where the app runs', 'EXPO_PUBLIC_API_URL'],
    [
      ['Android emulator', '`http://10.0.2.2:4000`'],
      ['iOS simulator', '`http://127.0.0.1:4000`'],
      ['Phone with Expo Go', '`http://<your computer’s LAN IP>:4000`'],
    ],
    [3600, CONTENT - 3600],
  ),
  h2('5. Optional: tests and demos'),
  ...code([
    'npm run test:offline        # no network or credentials needed',
    'npm run test:hosted         # against your Supabase project',
    'npm run db:reset-reference  # restore the three reference meetups',
    'npm run live:simulate       # simulated walkers for the live walk demo',
  ]),

  // Appendix A
  h1('Appendix A. Demo accounts'),
  p('Every demo account uses the password **altair-fixture-pass**. These accounts are for demonstration and testing only.'),
  ...table(
    ['Name', 'Email', 'Groups', 'Good for trying'],
    [
      ['Avery Lin', 'avery@example.test', 'Maple Street Walkers', 'Hosting: edit and cancel “Saturday morning loop”'],
      ['Jordan Price', 'jordan@example.test', 'Maple Street Walkers', 'Going to Saturday; hosts “Weeknight short walk”'],
      ['Sam Okafor', 'sam@example.test', 'Maple Street Walkers', 'Before/after RSVP: approximate vs exact point'],
      ['Riley Chen', 'riley@example.test', 'Both groups', 'Switching groups; going to Saturday only'],
      ['Morgan Ellis', 'morgan@example.test', 'Riverside Loop Walkers', 'Hosts “Riverside sunrise walk”'],
      ['Casey Moreno', 'casey@example.test', 'Riverside Loop Walkers', 'Going to Riverside sunrise walk'],
      ['Quinn Adler', 'quinn@example.test', 'Riverside Loop Walkers', 'Member who has not RSVP’d'],
      ['Taylor Brooks', 'taylor@example.test', 'None', 'Outsider: sees no groups or meetups'],
    ],
    [1650, 2350, 2200, CONTENT - 6200],
  ),
  p('Place names and coordinates in the demo data are fictional and do not match the real-world map labels at those coordinates.', { run: { italics: true, color: C.muted, size: 20 } }),
];

// ---------------------------------------------------------------- document
const footer = new Footer({
  children: [
    new Paragraph({
      border: { top: { style: BorderStyle.SINGLE, size: 4, color: C.rule, space: 6 } },
      children: [
        new TextRun({ text: 'Altair Meetups · User Guide', size: 17, color: C.muted }),
        new TextRun({
          size: 17,
          color: C.muted,
          children: [
            new PositionalTab({ alignment: PositionalTabAlignment.RIGHT, relativeTo: PositionalTabRelativeTo.MARGIN, leader: PositionalTabLeader.NONE }),
            'Page ',
            PageNumber.CURRENT,
            ' of ',
            PageNumber.TOTAL_PAGES,
          ],
        }),
      ],
    }),
  ],
});

const page = { size: { width: 11906, height: 16838 }, margin: { top: 1300, bottom: 1300, left: 1300, right: 1300, footer: 600 } };

const doc = new Document({
  creator: 'Altair',
  title: 'Altair Meetups User Guide',
  description: 'User guide for the Altair group meetups app',
  features: { updateFields: true },
  styles: {
    default: { document: { run: { font: FONT, size: 22, color: C.text } } },
    paragraphStyles: [
      {
        id: 'Heading1', name: 'Heading 1', basedOn: 'Normal', next: 'Normal', quickFormat: true,
        run: { size: 34, bold: true, color: C.green, font: FONT },
        paragraph: {
          spacing: { before: 120, after: 200 }, keepNext: true, outlineLevel: 0,
          border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: C.mint, space: 6 } },
        },
      },
      {
        id: 'Heading2', name: 'Heading 2', basedOn: 'Normal', next: 'Normal', quickFormat: true,
        run: { size: 26, bold: true, color: C.text, font: FONT },
        paragraph: { spacing: { before: 280, after: 120 }, keepNext: true, outlineLevel: 1 },
      },
    ],
  },
  numbering: {
    config: [
      {
        reference: 'bullets',
        levels: [{ level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 400, hanging: 260 } }, run: { color: C.green } } }],
      },
      {
        reference: 'steps',
        levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 440, hanging: 340 } }, run: { bold: true, color: C.green } } }],
