});

fs.mkdirSync(path.dirname(OUT), { recursive: true });
Packer.toBuffer(doc).then((buffer) => {
  fs.writeFileSync(OUT, buffer);
  console.log(`wrote ${OUT} (${Math.round(buffer.length / 1024)} KB, ${figureNo} figures)`);
