// Temporary: delete the manually created test meetup titled "Xxx" from the hosted DB.
import pg from 'pg';
import { loadDotEnv, readServerEnv } from '../src/config/env';

loadDotEnv();
const client = new pg.Client({ connectionString: readServerEnv().DATABASE_URL });
await client.connect();
try {
  await client.query('begin');
  const found = await client.query(
    `select m.id, m.title, m.status, m.starts_at, g.name as group_name, u.display_name as creator,
            (select count(*)::int from public.rsvps r where r.meetup_id = m.id) as rsvps
       from public.meetups m
       join public.groups g on g.id = m.group_id
       left join public.users u on u.id = m.created_by
      where m.title = 'Xxx'`,
  );
  console.log('matches:', found.rows);
  const target = found.rows[0];
  if (found.rowCount !== 1 || String(target.id).startsWith('c3000000-')) {
    throw new Error(`refusing to delete: expected exactly one non-reference match, got ${found.rowCount}`);
  }
  const deleted = await client.query('delete from public.meetups where id = $1', [target.id]);
  await client.query('commit');
  console.log(`deleted ${deleted.rowCount} meetup (${target.id}); meeting point and RSVPs cascaded`);
  const left = await client.query(`select title, status from public.meetups order by starts_at`);
  console.log('meetups now:', left.rows);
} catch (error) {
  await client.query('rollback').catch(() => undefined);
  throw error;
} finally {
  await client.end();
}

